/* 入库工作台增量架构；执行前必须先人工审核 012_InboundWorkspace_Preflight.sql。 */
SET NOCOUNT ON; SET XACT_ABORT ON;
BEGIN TRY
 BEGIN TRANSACTION;
 IF OBJECT_ID(N'dbo.PurchaseReceiveHead',N'U') IS NULL OR OBJECT_ID(N'dbo.PurchaseReceiveLine',N'U') IS NULL THROW 51200,N'入库迁移阻断：缺少既有 PurchaseReceiveHead/Line。',1;
 IF COL_LENGTH(N'dbo.PurchaseReceiveHead',N'DocumentType') IS NULL ALTER TABLE dbo.PurchaseReceiveHead ADD DocumentType smallint NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveHead',N'LifecycleStatus') IS NULL ALTER TABLE dbo.PurchaseReceiveHead ADD LifecycleStatus tinyint NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveHead',N'PostingStatus') IS NULL ALTER TABLE dbo.PurchaseReceiveHead ADD PostingStatus tinyint NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveHead',N'WarehouseSiteId') IS NULL ALTER TABLE dbo.PurchaseReceiveHead ADD WarehouseSiteId uniqueidentifier NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveHead',N'WarehouseCode') IS NULL ALTER TABLE dbo.PurchaseReceiveHead ADD WarehouseCode nvarchar(50) NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveHead',N'WarehouseNameSnapshot') IS NULL ALTER TABLE dbo.PurchaseReceiveHead ADD WarehouseNameSnapshot nvarchar(200) NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveHead',N'SupplierId') IS NULL ALTER TABLE dbo.PurchaseReceiveHead ADD SupplierId uniqueidentifier NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveHead',N'SupplierNameSnapshot') IS NULL ALTER TABLE dbo.PurchaseReceiveHead ADD SupplierNameSnapshot nvarchar(200) NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveHead',N'PostedDate') IS NULL ALTER TABLE dbo.PurchaseReceiveHead ADD PostedDate datetime2 NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveHead',N'PostedBy') IS NULL ALTER TABLE dbo.PurchaseReceiveHead ADD PostedBy nvarchar(100) NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveHead',N'ReversedDate') IS NULL ALTER TABLE dbo.PurchaseReceiveHead ADD ReversedDate datetime2 NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveHead',N'ReversedBy') IS NULL ALTER TABLE dbo.PurchaseReceiveHead ADD ReversedBy nvarchar(100) NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveHead',N'ReverseReason') IS NULL ALTER TABLE dbo.PurchaseReceiveHead ADD ReverseReason nvarchar(1000) NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveHead',N'SourcePackingListId') IS NULL ALTER TABLE dbo.PurchaseReceiveHead ADD SourcePackingListId uniqueidentifier NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveHead',N'CommandId') IS NULL ALTER TABLE dbo.PurchaseReceiveHead ADD CommandId uniqueidentifier NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveLine',N'PurchaseReceiveHeadId') IS NULL THROW 51201,N'入库迁移阻断：需人工确认既有收货明细父键列。',1;
 IF COL_LENGTH(N'dbo.PurchaseReceiveLine',N'ProductId') IS NULL ALTER TABLE dbo.PurchaseReceiveLine ADD ProductId uniqueidentifier NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveLine',N'LineNumber') IS NULL ALTER TABLE dbo.PurchaseReceiveLine ADD LineNumber int NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveLine',N'Quantity') IS NULL ALTER TABLE dbo.PurchaseReceiveLine ADD Quantity decimal(18,4) NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveLine',N'SourceType') IS NULL ALTER TABLE dbo.PurchaseReceiveLine ADD SourceType smallint NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveLine',N'SourceUid') IS NULL ALTER TABLE dbo.PurchaseReceiveLine ADD SourceUid uniqueidentifier NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveLine',N'DemandExecutionLinkId') IS NULL ALTER TABLE dbo.PurchaseReceiveLine ADD DemandExecutionLinkId uniqueidentifier NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveLine',N'NetDemandAllocationId') IS NULL ALTER TABLE dbo.PurchaseReceiveLine ADD NetDemandAllocationId uniqueidentifier NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveLine',N'GrossDemandId') IS NULL ALTER TABLE dbo.PurchaseReceiveLine ADD GrossDemandId uniqueidentifier NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveLine',N'SalesOrderNoSnapshot') IS NULL ALTER TABLE dbo.PurchaseReceiveLine ADD SalesOrderNoSnapshot nvarchar(100) NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveLine',N'SalesOrderLineNumberSnapshot') IS NULL ALTER TABLE dbo.PurchaseReceiveLine ADD SalesOrderLineNumberSnapshot int NULL;
 IF COL_LENGTH(N'dbo.PurchaseReceiveLine',N'OriginalLineId') IS NULL ALTER TABLE dbo.PurchaseReceiveLine ADD OriginalLineId uniqueidentifier NULL;
 IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.PurchaseReceiveHead') AND name=N'UX_PurchaseReceiveHead_CommandId_012') CREATE UNIQUE INDEX UX_PurchaseReceiveHead_CommandId_012 ON dbo.PurchaseReceiveHead(CommandId) WHERE ISNULL(IsDeleted,0)=0 AND CommandId IS NOT NULL;
 IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.PurchaseReceiveLine') AND name=N'IX_PurchaseReceiveLine_Source_012') CREATE INDEX IX_PurchaseReceiveLine_Source_012 ON dbo.PurchaseReceiveLine(SourceType,SourceUid) INCLUDE(Quantity,PurchaseReceiveHeadId) WHERE ISNULL(IsDeleted,0)=0 AND SourceUid IS NOT NULL;
 COMMIT TRANSACTION;
END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK TRANSACTION; THROW; END CATCH;
